contract InvMutTest {
    C c;
    address public poolCaller;
    constructor(C _c) { c = _c; poolCaller = address(0x100); }

    // We need to simulate a curated pool calling c.mintSynth. The contract C checks
    // only that msg.sender is a curated pool via iPOOLFACTORY(...).isCuratedPool(msg.sender).
    // We cannot change external factory, but the checker deploys a fresh C and may set up
    // environment where poolCaller is considered curated by that DAO. To stay conservative
    // and still express a verifier-checkable invariant, we call mintSynth via low-level
    // call from this contract but treat the possibility of revert. We then assert the
    // stated relation holds whenever the call did NOT revert.

    // Single public function with parameters: address member (recipient) and uint amount.
    function run(address member, uint amount) public payable {
        require(member != address(0));

        // Read before-values
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(address(this));
        // Attempt to call mintSynth with this contract as the pool (msg.sender == this)
        // We perform the call directly so msg.sender for C.mintSynth is address(this) which
        // will act as the pool in C's logic. Some environments may reject (revert) if not curated;
        // capture whether it reverted.
        bool reverted = false;
        // Call encoded: mintSynth(address member, uint amount)
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("mintSynth(address,uint256)", member, amount));
        if(!ok) { reverted = true; }

        // Read after-values (always callable even if prior call reverted)
        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(address(this));

        // If the call did not revert, then totalSupply increased by amount and mapSynth_LPDebt increased by amount.
        // Note: mintSynth returns the minted amount; we assert the conservative relation that after = before + amount.
        assert(reverted || (afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to have this contract act as the pool caller. The test checks the relation
    // only when the call does not revert. The call must be a direct top-level call to c.
    function run(address member, uint256 amount) public payable {
        require(member != address(0));

        // Read before-values via public getters
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeDebt = c.getmapAddress_LPDebt(address(this));

        // Direct call: msg.sender for c.mintSynth will be this contract
        bool didRevert;
        try c.mintSynth(member, amount) returns (uint256 minted) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterDebt = c.getmapAddress_LPDebt(address(this));

        // If the call succeeded, totalSupply and the pool's recorded debt increased by exactly amount
        assert(didRevert || (afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount));
    }

    receive() external payable {}
}

