contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the fuzzer: pool must be an address (the pool contract)
    // amount is the synthetic amount the pool will mint for member
    function run(address pool, address member, uint amount) public payable {
        require(pool != address(0) && member != address(0));

        // Observe before values
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);

        // Attempt the call from the pool context: since the checker will deploy a fresh C
        // and this InvMutTest is the deployer of C, we cannot change msg.sender for c.mintSynth.
        // However, the contract C restricts mintSynth with onlyPool modifier which checks
        // the POOLFACTORY.isCuratedPool(msg.sender). That call may revert if pool isn't curated.
        // So we must call mintSynth via low-level call to simulate pool as msg.sender by invoking
        // the pool address to call c.mintSynth. We cannot deploy pool here; instead we try calling
        // c.mintSynth directly and record revert. The property only needs to hold for successful calls.

        bool reverted = false;
        // Call c.mintSynth(pool member amount) directly; if it reverts, mark reverted.
        try c.mintSynth(member, amount) returns (uint minted) {
            // minted returned when msg.sender (this contract) is allowed (i.e., isCuratedPool). If it succeeds,
            // we expect totalSupply and mapSynth_LPDebt changed accordingly.
        } catch {
            reverted = true;
        }

        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(pool);

        // If the call reverted, the state must be unchanged for the observed slots.
        // If it did not revert, then totalSupply increased by exactly 'amount' and mapSynth_LPDebt[pool] increased by 'amount'.
        assert(
            (reverted && afterTotal == beforeTotal && afterDebt == beforeDebt)
            || (!reverted && afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // pool: the pool address (expected msg.sender when mintSynth is called)
    // member: recipient of minted synths
    // amount: amount to mint
    function run(address pool, address member, uint amount) public payable {
        require(pool != address(0) && member != address(0));

        // Observe before values via public getters
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);

        bool reverted = false;
        uint returnedMinted = 0;
        // Call mintSynth on c as this contract (msg.sender = this). The function may revert depending on poolFactory.
        try c.mintSynth(member, amount) returns (uint minted) {
            returnedMinted = minted;
        } catch {
            reverted = true;
        }

        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(pool);

        // General rule: if the call reverted, observed state must be unchanged; otherwise totalSupply and debt increased by amount
        assert(
            (reverted && afterTotal == beforeTotal && afterDebt == beforeDebt)
            || (!reverted && returnedMinted == amount && afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount)
        );
    }

    receive() external payable {}
}

