contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // pool: the pool address that will call burnSynth on c
    function run(address pool) public payable {
        require(pool != address(0));

        // Observe before values via public getters
        uint beforeLPBal = c.getmapAddress_LPBalance(pool);
        uint beforeLPDebt = c.getmapAddress_LPDebt(pool);

        bool reverted = false;
        bool returned = false;

        // Call burnSynth on c; msg.sender for that call will be this contract
        // The call may revert; capture that
        try c.burnSynth{gas: gasleft()}() returns (bool ok) {
            returned = ok;
        } catch {
            reverted = true;
        }

        uint afterLPBal = c.getmapAddress_LPBalance(pool);
        uint afterLPDebt = c.getmapAddress_LPDebt(pool);

        // If reverted: balances must be unchanged.
        // If succeeded: LP debt must have decreased by at most the previous debt and by exactly the amount of synthetic burned
        // We cannot directly read how many synth were burned, but totalSupply change is observable and the function burns balanceOf(address(this)) synths from C when called by pool.
        // The rule we assert: either unchanged on revert, or debt decreased and LP balance decreased by <= previous LP balance.
        assert(
            (reverted && afterLPBal == beforeLPBal && afterLPDebt == beforeLPDebt)
            || (!reverted && afterLPDebt <= beforeLPDebt && beforeLPBal >= afterLPBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
