    // pool will act as msg.sender when calling burnSynth on c
    function run(address pool) public payable {
        require(pool != address(0));

        // observe before-values using public getters
        uint beforeLPBal = c.getmapAddress_LPBalance(pool);
        uint beforeLPDebt = c.getmapAddress_LPDebt(pool);

        bool reverted = false;
        bool returned = false;
        try c.burnSynth{gas: gasleft()}() returns (bool ok) {
            returned = ok;
        } catch {
            reverted = true;
        }

        uint afterLPBal = c.getmapAddress_LPBalance(pool);
        uint afterLPDebt = c.getmapAddress_LPDebt(pool);

        // General invariant:
        // - If the call reverted, both tracked values must be unchanged.
        // - If it succeeded, LP debt cannot increase and cannot decrease below zero (i.e. <= beforeLPDebt),
        //   and LP balance must not increase (it may decrease or stay the same).
        assert(
            (reverted && afterLPBal == beforeLPBal && afterLPDebt == beforeLPDebt)
            || (!reverted && afterLPDebt <= beforeLPDebt && afterLPBal <= beforeLPBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We simulate a curated pool calling mintSynth by invoking c.mintSynth from this contract.
    // Inputs:
    // - address pool: address of the pool (must be treated abstractly). In the real system the pool must be curated;
    //   here we don't require that, but the property will still record observable effects when the call succeeds.
    // - address member: recipient of minted synth tokens
    // - uint amount: synthetic amount requested
    function run(address pool, address member, uint256 amount) public payable {
        require(member != address(0), "member0");
        // read before-values
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeLPBalance = c.getmapAddress_LPBalance(pool);
        uint beforeMemberBal = c.balanceOf(member);

        bool reverted;
        uint minted;
        // call that may revert if pool not curated; capture revert flag
        try c.mintSynth(member, amount) {
            reverted = false;
            // If the call succeeded, read after-values
            minted = c.balanceOf(member) - beforeMemberBal;
        } catch {
            reverted = true;
            minted = 0;
        }

        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterLPBalance = c.getmapAddress_LPBalance(pool);

        // General rule:
        // If c.mintSynth did not revert then (1) the member's balance increased by exactly `amount`,
        // and (2) the recorded LP debt for the pool increased by exactly `amount`,
        // and (3) the recorded LP balance for the pool did not decrease (it is >= previous value).
        assert(reverted || (minted == amount && afterDebt == beforeDebt + amount && afterLPBalance >= beforeLPBalance));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Simulate a curated pool calling burnSynth on C by invoking c.burnSynth from this contract.
    // Inputs:
    // - address pool: the pool address (msg.sender for calls from pool in real system)
    // No Ether needed.
    function run(address pool) public payable {
        require(pool != address(0), "pool0");
        // Observe before-values
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeLPBalance = c.getmapAddress_LPBalance(pool);
        uint beforePoolTokenBalance = c.balanceOf(pool);

        bool reverted;
        // call that may revert (onlyPool modifier may block it); capture revert flag
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterLPBalance = c.getmapAddress_LPBalance(pool);
        uint afterPoolTokenBalance = c.balanceOf(pool);

        // General rule:
        // If the call did not revert then the recorded LP debt for the pool decreased by exactly the
        // amount of synthetic tokens that C had (i.e. beforePoolTokenBalance), and the recorded LP balance
        // did not increase (it is <= previous value). Also afterPoolTokenBalance equals 0 when successful
        // because C burns its entire synthetic balance in burnSynth.
        assert(reverted || (afterDebt + beforePoolTokenBalance == beforeDebt && afterLPBalance <= beforeLPBalance && afterPoolTokenBalance == 0));
    }

    receive() external payable { }
}

