contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Simulate a pool (msg.sender) invoking burnSynth on c by calling c.burnSynth() from this contract.
    // Input: pool address is used only to observe public mappings for that pool.
    function run(address pool) public payable {
        require(pool != address(0), "pool0");

        // Observe before-values via public getters
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeLPBalance = c.getmapAddress_LPBalance(pool);
        uint beforePoolTokenBalance = c.balanceOf(pool);

        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterLPBalance = c.getmapAddress_LPBalance(pool);
        uint afterPoolTokenBalance = c.balanceOf(pool);

        // If the call did not revert then:
        // - the debt must have decreased by exactly the synthetic amount C held before the call (beforePoolTokenBalance)
        // - the stored LP balance must not have increased
        // - the token balance of the pool (as seen by C.balanceOf(pool)) must be zero
        assert(reverted || (afterDebt + beforePoolTokenBalance == beforeDebt && afterLPBalance <= beforeLPBalance && afterPoolTokenBalance == 0));
    }

    receive() external payable { }
}

