contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We act as a pool calling c.mintSynth(member, amount).
    // Parameters:
    // - address member: recipient of minted synths
    // - uint256 amount: synthetic amount requested
    // Preconditions: none (we allow any inputs)
    function run(address poolCaller, address member, uint256 amount) public payable {
        require(poolCaller != address(0) && member != address(0));

        // We will simulate calls coming from poolCaller by using low-level call to c with msg.sender == address(this).
        // But the contract C enforces onlyPool via iPOOLFACTORY check on msg.sender. The checker deploys a fresh C
        // and will set poolFactory such that poolCaller may or may not be curated. We cannot change msg.sender, so
        // instead we will invoke c.mintSynth via a delegatecall-like pattern is not allowed. However the constraint
        // requires all state-changing calls on c to be top-level. To satisfy that and still test behavior, we
        // observe that c.mintSynth uses only msg.sender to index maps; so we perform the call directly (msg.sender == this)
        // and then reason about the relationship between returned amount and state change. We'll call c.mintSynth and
        // capture whether it reverted.

        // Record observables before call
        uint256 totalBefore = c.totalSupply();
        uint mapDebtBefore = c.getmapAddress_LPDebt(address(this));
        bool reverted;
        // perform the call: since onlyPool modifier may revert, catch it
        try c.mintSynth(member, amount) returns (uint minted) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint mapDebtAfter = c.getmapAddress_LPDebt(address(this));

        // General rule:
        // If the call reverted, then totalSupply and mapSynth_LPDebt must be unchanged; otherwise
        // totalSupply increased by exactly the minted amount and mapSynth_LPDebt increased by that same amount.
        // We can't directly access 'minted' from the try branch here in the assert (to keep single assert condition),
        // so we assert the equivalence: (not reverted) implies (totalAfter - totalBefore == mapDebtAfter - mapDebtBefore && totalAfter >= totalBefore),
        // and reverted implies equality of before/after.

        assert(
            (reverted && totalAfter == totalBefore && mapDebtAfter == mapDebtBefore)
            ||
            (!reverted && totalAfter >= totalBefore && mapDebtAfter >= mapDebtBefore && (totalAfter - totalBefore) == (mapDebtAfter - mapDebtBefore))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We act as the pool (msg.sender == this) calling c.mintSynth(member, amount).
    // Parameters:
    // - address member: recipient of minted synths
    // - uint256 amount: synthetic amount requested
    // No precondition on member/amount beyond non-zero addresses to avoid trivial degenerate calls.
    function run(address member, uint256 amount) public payable {
        require(member != address(0));

        // Observables before call for this caller (this contract will be msg.sender when calling c)
        uint256 totalBefore = c.totalSupply();
        uint256 debtBefore = c.getmapAddress_LPDebt(address(this));

        bool reverted;
        uint256 mintedReturned = 0;
        // Call mintSynth from this contract (this impersonates a pool). Capture revert status.
        try c.mintSynth(member, amount) returns (uint256 minted) {
            reverted = false;
            mintedReturned = minted;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 debtAfter = c.getmapAddress_LPDebt(address(this));

        // Assert the invariant:
        // - If the call reverted then totalSupply and mapSynth_LPDebt for this pool are unchanged.
        // - Otherwise, both increased and the increase in totalSupply equals the increase in mapSynth_LPDebt.
        // (Also ensure non-decreasing individually to avoid weird underflows inside the assert.)
        assert(
            (reverted && totalAfter == totalBefore && debtAfter == debtBefore)
            ||
            (!reverted && totalAfter >= totalBefore && debtAfter >= debtBefore && (totalAfter - totalBefore) == (debtAfter - debtBefore) && (totalAfter - totalBefore) == mintedReturned)
        );
    }

    receive() external payable { }
}

