contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: pool address (must be a curated pool in DAO in real env) and amount to mint
    function run(address pool, uint256 amount) public payable {
        require(pool != address(0) && amount > 0, "pre");

        // observe before-state
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeRecipientBal = c.balanceOf(address(this));
        uint256 beforeLPBalance = c.getmapAddress_LPBalance(pool);
        uint256 beforeLPDebt = c.getmapAddress_LPDebt(pool);

        // call mintSynth as if from pool: since the checker deploys c and this contract is the caller,
        // we simulate the pool calling by using low-level call with msg.sender spoofing not possible.
        // But rule must be about behavior when a pool (curated) calls mintSynth: here we call it directly
        // (the function has onlyPool modifier which may revert; capture revert flag).
        bool reverted;
        try c.mintSynth(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterRecipientBal = c.balanceOf(address(this));
        uint256 afterLPBalance = c.getmapAddress_LPBalance(pool);
        uint256 afterLPDebt = c.getmapAddress_LPDebt(pool);

        // General rule: if the call succeeded (not reverted) then totalSupply and recipient balance increased by exactly 'amount',
        // and the pool's recorded LP debt increased by exactly 'amount', and LP balance did not decrease.
        // if reverted, no observable increases should have occurred.
        assert(
            // success case: precise minting and accounting
            (!reverted && afterTotal == beforeTotal + amount && afterRecipientBal == beforeRecipientBal + amount && afterLPDebt == beforeLPDebt + amount && afterLPBalance >= beforeLPBalance)
            // or reverted case: nothing increased (no partial side-effects expected)
            || (reverted && afterTotal == beforeTotal && afterRecipientBal == beforeRecipientBal && afterLPDebt == beforeLPDebt && afterLPBalance == beforeLPBalance)
        );
    }

    receive() external payable {}
}

