        uint beforeSupply = c.totalSupply();
        uint beforePoolDebt = c.getmapAddress_LPDebt(pool);
        uint beforePoolLPBal = c.getmapAddress_LPBalance(pool);
        uint beforeThisBal = c.balanceOf(address(this));

        // Call burnSynth as this contract but the Pool must be msg.sender; we cannot change msg.sender.
        // However burnSynth uses msg.sender to index mapSynth_* and to call Pool(msg.sender).burn(...).
        // The checker deploys a fresh C with this test as deployer; to simulate a Pool caller we simply call burnSynth
        // and reason about observable effects: regardless of caller identity, burnSynth either reverts or executes.
        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint afterSupply = c.totalSupply();
        uint afterPoolDebt = c.getmapAddress_LPDebt(pool);
        uint afterPoolLPBal = c.getmapAddress_LPBalance(pool);
        uint afterThisBal = c.balanceOf(address(this));

        // General rule:
        // - If call reverted: nothing guaranteed (we accept revert).
        // - If call succeeded: then either no synthetic balance existed for C (so no burn happened) -> no observable changes,
        //   or C had positive synthetic balance at address(this) and the function burned exactly that balance: then totalSupply and
        //   address(this) balance both decreased by the same positive amount, and the pool's recorded debt and LP balance did not increase.
        bool succ_no_change = (!reverted && afterSupply == beforeSupply && afterThisBal == beforeThisBal && afterPoolDebt == beforePoolDebt && afterPoolLPBal == beforePoolLPBal);
        bool succ_burned = false;
        if(!reverted) {
            // detect a positive burn that decreased both totalSupply and this balance by same amount, and pool mappings not increased
            if(beforeThisBal > afterThisBal) {
                uint deltaSupply = beforeSupply - afterSupply;
                uint deltaThis = beforeThisBal - afterThisBal;
                succ_burned = (deltaSupply == deltaThis) && (deltaSupply > 0) && (afterPoolDebt <= beforePoolDebt) && (afterPoolLPBal <= beforePoolLPBal);
            }
        }

        assert(reverted || succ_no_change || succ_burned);
    }

    // receive to accept any ETH if needed by calls
    receive() external payable { }
}

