            (reverted && afterTotal == beforeTotal && afterDebt == beforeDebt)
            || (!reverted && afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take the caller pool address and an amount to mint. The test will call c.mintSynth
    // as if invoked by a curated pool. However the checker deploys a fresh C and will have
    // msg.sender be this test contract. To simulate a call from a pool we rely on the fact
    // that mintSynth has onlyPool modifier which checks iPOOLFACTORY(...).isCuratedPool(msg.sender).
    // We cannot change external factories; therefore we test the general invariant in two cases:
    // - if the call reverts (not curated), then the revert flag must be true
    // - if it does not revert, then totalSupply increases by exactly the returned minted amount,
    //   and c.getmapAddress_LPDebt(pool) and c.getmapAddress_LPBalance(pool) reflect non-decreasing updates.

    function run(address pool, address member, uint amount) public payable {
        require(member != address(0), "member0");
        // record before-values
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeBalance = c.getmapAddress_LPBalance(pool);

        bool reverted = false;
        uint ret = 0;
        // Attempt the state-changing call as top-level statement and capture revert
        try c.mintSynth(member, amount) returns (uint syntheticAmount) {
            ret = syntheticAmount;
        } catch {
            reverted = true;
        }

        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterBalance = c.getmapAddress_LPBalance(pool);

        // The property: either the call reverted (not curated) OR
        // if it succeeded then totalSupply increased by exactly the returned amount,
        // and the pool's recorded debt increased by at least the minted amount and LP balance did not decrease.
        // We express "increased by exactly" as afterTotal == beforeTotal + ret.
        // For debt we require afterDebt >= beforeDebt and afterBalance >= beforeBalance.
        assert(reverted || (ret > 0 && afterTotal == beforeTotal + ret && afterDebt >= beforeDebt && afterBalance >= beforeBalance));
    }

    receive() external payable {}
 }

